from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        if key not in cache:
            return True
        _, wt = cache[key]
        return t >= wt + ttl

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # clean expired for this key if present
            if key in cache and is_expired(key, t):
                del cache[key]

            if key in cache:
                # update existing, move to most recently used
                del cache[key]
                cache[key] = (value, t)
            else:
                if len(cache) >= capacity:
                    # evict least recently used, but first check if it's expired anyway
                    cache.popitem(last=False)
                cache[key] = (value, t)
        else:
            _, t, key = op
            if key in cache and not is_expired(key, t):
                value, wt = cache[key]
                del cache[key]
                cache[key] = (value, wt)
                results.append(value)
            else:
                if key in cache:
                    del cache[key]
                results.append(-1)

    return results

